import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
const root=path.dirname(fileURLToPath(import.meta.url));
const c=JSON.parse(fs.readFileSync(path.join(root,'context.json'))),stage=c.assigned_workflow,identity=c.tasks[stage];
const input=JSON.parse(fs.readFileSync(0,'utf8'));
if(input.run!==identity.run_tag||input.line!==c.line)throw Error('BUSINESS_SCOPE');
for(const [f,h] of Object.entries(c.verification.runtime_sha256))if(crypto.createHash('sha256').update(fs.readFileSync(path.join(c.runtime_root,f))).digest('hex')!==h)throw Error('RUNTIME_SOURCE_CHANGED');
const require=createRequire(path.join(c.runtime_root,'package.json')),pool=require('./leadgen-db-connect.js').getPool();
try{
 const rows=(await pool.query('SELECT company_id,tenant_id,config_version,runtime_config,config_status FROM zenithjoy.tenant_company_profiles WHERE company_id=$1',[c.company_id])).rows;
 if(rows.length!==1||rows[0].tenant_id!==c.tenant_id||Number(rows[0].config_version)!==c.verification.policy_version||rows[0].config_status!=='enabled')throw Error('CURRENT_COMPANY_POLICY_DRIFT');
 const execution={...identity,run:identity.run_tag,line:c.line,profile:c.profile,root_task_id:c.root_task_id,actor:c.actor};
 const result=await require('./leadgen-queue.js').queueRequest(pool,input,{sourceCommit:c.source_commit,execution});
 let details;
 if(input.op==='company_config'){
  const frozen=(await pool.query('SELECT snapshot FROM zenithjoy.company_config_runs WHERE company_id=$1 AND run_id=$2',[c.company_id,identity.run_tag])).rows;
  if(frozen.length!==1||Number(frozen[0].snapshot.version)!==c.verification.policy_version)throw Error('FROZEN_POLICY_MISMATCH');
  details=frozen[0].snapshot;
 }
 console.log(JSON.stringify({ok:true,result,details}));
}finally{await pool.end();}

